<template>
  <q-select
    :model-value="modelValue"
    :options="allOptions"
    :label="label"
    outlined
    dense
    emit-value
    map-options
    clearable
    class="assignee-picker"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <template #option="{ opt, itemProps }">
      <!-- Group header -->
      <q-item-label
        v-if="opt.header"
        header
        class="assignee-picker__group-header"
      >
        <q-icon :name="opt.icon" size="16px" class="q-mr-xs" />
        {{ opt.label }}
      </q-item-label>

      <!-- Option item -->
      <q-item v-else v-bind="itemProps" dense class="assignee-picker__option">
        <q-item-section avatar class="assignee-picker__avatar-section">
          <q-avatar size="24px" :color="opt.type === 'agent' ? 'primary' : 'blue-grey-6'" text-color="white">
            <q-icon :name="opt.type === 'agent' ? 'smart_toy' : 'person'" size="14px" />
          </q-avatar>
        </q-item-section>
        <q-item-section>
          <q-item-label>{{ opt.label }}</q-item-label>
          <q-item-label v-if="opt.role" caption>{{ opt.role }}</q-item-label>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export interface AssigneeOption {
  label: string;
  value: string;
  type: 'agent' | 'human';
  role?: string;
  workload?: number;
  header?: boolean;
  icon?: string;
}

export default defineComponent({
  name: 'AssigneePicker',

  props: {
    modelValue: {
      type: String,
      default: '',
    },
    agents: {
      type: Array as PropType<AssigneeOption[]>,
      default: () => [],
    },
    humans: {
      type: Array as PropType<AssigneeOption[]>,
      default: () => [],
    },
    label: {
      type: String,
      default: 'Assignee',
    },
  },

  emits: ['update:modelValue'],

  computed: {
    allOptions(): AssigneeOption[] {
      const options: AssigneeOption[] = [];

      if (this.humans.length > 0) {
        options.push({
          label: 'Team Members',
          value: '__header_humans',
          type: 'human',
          header: true,
          icon: 'group',
        });
        options.push(...this.humans);
      }

      if (this.agents.length > 0) {
        options.push({
          label: 'Agents',
          value: '__header_agents',
          type: 'agent',
          header: true,
          icon: 'smart_toy',
        });
        options.push(...this.agents);
      }

      return options;
    },
  },
});
</script>

